const Validator = {
  validateEmail(email) { const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/; return re.test(String(email).toLowerCase()); },
  validateCardNumber(cardNum) { const clean = String(cardNum).replace(/\D/g, ''); return clean.length >= 13 && clean.length <= 19; },
  sanitizeHTML(str) { return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
};

if (typeof window !== 'undefined') { window.Validator = Validator; }
if (typeof module !== 'undefined' && module.exports) { module.exports = { Validator, ValidationRules }; }